<script setup lang="ts">
import DecimalInput from "../components/DecimalInput.vue"
import { onMounted, ref } from 'vue'
import { useI18n } from 'vue-i18n'
import { api, json } from '../api'
import { channels, categories, rateKeys, cashRates, type Settings } from '../types'
import { useApp } from '../stores/app'
import Icon from '../components/Icon.vue'
const { t } = useI18n(); const app = useApp(); const settings = ref<Settings>(); const channel = ref('shelf'); const busy = ref(false); const versions = ref<Settings[]>([])
onMounted(async () => { try { settings.value = await api<Settings>('/settings'); versions.value = await api<Settings[]>('/settings/versions') } catch(e) { app.report(e) } })
async function save() { if (!settings.value) return; busy.value = true; app.clear(); try { settings.value = await api<Settings>('/settings',json('PUT',settings.value)); app.settings = settings.value; versions.value.push(settings.value); app.success(t('settingsSuccess')) } catch(e) { app.report(e) } finally { busy.value = false } }
</script>
<template><div class="page-heading"><div><span class="eyebrow"><span class="eyebrow-line"></span>{{ t('settings') }}</span><h1>{{ t('settingsTitle') }}</h1><p>{{ t('settingsSub') }}</p></div><span v-if="settings" class="version-pill">{{ t('presetVersion') }} {{ settings.version }}</span></div><div v-if="!settings" class="loading-state">{{ t('loading') }}</div><template v-else><div class="settings-notice"><Icon name="info" /><p>{{ t('presetHint') }}</p></div><section class="panel form-panel"><div class="section-title"><span class="section-icon"><Icon name="layers" /></span><div><h3>{{ t('assumptions') }}</h3><p>{{ t('channelsLabel') }}</p></div></div><div class="channel-tabs"><button v-for="c in channels" :key="c" :class="{ chosen: channel === c }" @click="channel = c">{{ t(c) }}</button></div><p v-if="channel === 'consignment'" class="muted small-text">{{ t('consignmentHint') }}</p><div class="form-grid settings-rates"><div v-for="k in rateKeys" :key="k" class="field"><label :for="`rate-${k}`">{{ t(k) }}<span>{{ cashRates.includes(k) ? 'Rp' : '%' }}</span></label><DecimalInput :id="`rate-${k}`" v-model="settings.channels[channel][k]" min="0" :max="cashRates.includes(k) ? 1000000000000 : 100" step="any" /></div></div></section><div class="settings-grid"><section class="panel form-panel"><div class="section-title"><span class="section-icon"><Icon name="box" /></span><div><h3>{{ t('categoryRates') }}</h3><p>{{ t('categoryRatesHint') }}</p></div></div><div class="category-rates"><div v-for="c in categories" :key="c" class="field"><label :for="`return-${c}`">{{ t(c) }}</label><div class="input-unit suffix"><DecimalInput :id="`return-${c}`" v-model="settings.categoryReturns[c]" min="0" max="100" step="any" :placeholder="t('preset')" /><span>%</span></div></div></div></section><section class="panel form-panel"><div class="section-title"><span class="section-icon"><Icon name="trend" /></span><div><h3>{{ t('grading') }}</h3></div></div><div class="form-grid"><div v-for="k in ['targetMargin','healthyMargin','healthyBuffer','viableMargin'] as const" :key="k" class="field"><label :for="k">{{ t(k) }}</label><div class="input-unit suffix"><DecimalInput :id="k" v-model="settings[k]" min="0" max="100" step="any" /><span>%</span></div></div></div></section></div><div class="form-actions"><span class="muted small-text">{{ versions.length }} {{ t('history').toLowerCase() }}</span><button class="btn primary" :disabled="busy" @click="save"><Icon name="check" />{{ t(busy ? 'saving' : 'saveSettings') }}</button></div></template></template>
